root=Path(__file__).parent; bundle=root.parent if root.name=='scripts' else root/'submission'; results=bundle/'results'; shots=bundle/'screenshots';bundle.mkdir(exist_ok=True)
pdfmetrics.registerFont(TTFont('SimSun',r'C:\Windows\Fonts\simsun.ttc',subfontIndex=0))
normal=ParagraphStyle('normal',fontName='Times-Roman',fontSize=10.5,leading=15,spaceAfter=8)
heading=ParagraphStyle('heading',parent=normal,fontName='Helvetica-Bold',fontSize=15,leading=21,spaceAfter=14)
small=ParagraphStyle('small',parent=normal,fontSize=8.7,leading=13)
caption=ParagraphStyle('caption',parent=small,alignment=TA_CENTER,spaceAfter=10)
story=[]; htmlparts=['<!doctype html><meta charset="utf-8"><style>body{font:16px Microsoft YaHei;max-width:1000px;margin:40px auto;line-height:1.8}img{max-width:100%}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:8px}</style>']
def p(text,style=normal):story.append(Paragraph(text,style));htmlparts.append('<p>'+text+'</p>')
def h(text):p(text,heading)
def page():story.append(PageBreak())
def figure(file,label,maxh=235):
 path=shots/file
 if not path.exists():raise FileNotFoundError(path)
 im=Image(str(path));scale=min(475/im.imageWidth,maxh/im.imageHeight);im.drawWidth=im.imageWidth*scale;im.drawHeight=im.imageHeight*scale;story.extend([im,Paragraph(label,caption)])
 htmlparts.append(f'<figure><img src="screenshots/{file}"><figcaption>{label}</figcaption></figure>')
def table(dataset):
 rows=[]
 for name in ['SIFT','SURF','ORB','FAST_BRIEF','LK']:
  path=results/dataset/(name+'_summary.csv')
  if path.exists():rows.append(next(csv.DictReader(path.open())))
 data=[['Method','Pairs','KP 1','KP 2','Raw','Good','Inliers','Ratio','Mean ms']]
 for r in rows:data.append([r['method'],r['pairs']]+[f"{float(r[k]):.1f}" for k in ['keypoints1','keypoints2','matches','good','inliers']]+[f"{float(r['inlier_ratio'])*100:.1f}%",f"{float(r['ms']):.2f}"])
 t=Table(data,colWidths=[64,32,46,46,46,46,46,48,47],repeatRows=1)
 t.setStyle(TableStyle([('FONTNAME',(0,0),(-1,-1),'Times-Roman'),('FONTSIZE',(0,0),(-1,-1),8),('LEADING',(0,0),(-1,-1),12),('GRID',(0,0),(-1,-1),.5,colors.HexColor('#D9D9D9')),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#EEEEEE')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('ALIGN',(1,0),(-1,-1),'CENTER'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story.extend([t,Spacer(1,12)]);htmlparts.append('<table>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in data)+'</table>');return rows
def describe(rows):
 desc=[r for r in rows if r['method']!='LK']
 best=max(desc,key=lambda r:float(r['inliers']));fast=min(desc,key=lambda r:float(r['ms']));ratio=max(desc,key=lambda r:float(r['inlier_ratio']))
 p(f"本序列中，描述子方法里 {best['method']} 的平均几何内点数最高，为 {float(best['inliers']):.1f}；{fast['method']} 的平均计算耗时最低，为 {float(fast['ms']):.2f} ms。最高平均内点率来自 {ratio['method']}，为 {float(ratio['inlier_ratio'])*100:.1f}%。这三个指标反映数量、代价和一致性，可能由不同方法占优。")
 lk=next(r for r in rows if r['method']=='LK')
 p(f"Harris+LK 每对帧平均成功跟踪 {float(lk['good']):.1f} 个点，其中 {float(lk['inliers']):.1f} 个通过几何验证，平均耗时 {float(lk['ms']):.2f} ms。其连续小位移假设适合相邻视频帧，但在遮挡或大运动下不能保证持续跟踪。")
def describe_en(rows):
 descriptors=[r for r in rows if r['method']!='LK'];best=max(descriptors,key=lambda r:float(r['inliers']));fast=min(descriptors,key=lambda r:float(r['ms']));ratio=max(descriptors,key=lambda r:float(r['inlier_ratio']))
 p(f"Among descriptor methods, {best['method']} produced the most geometric inliers on average ({float(best['inliers']):.1f}). {fast['method']} had the lowest mean computation time ({float(fast['ms']):.2f} ms). The highest mean inlier ratio was obtained by {ratio['method']} ({float(ratio['inlier_ratio'])*100:.1f}%). These quantities measure different aspects of performance.")
 lk=next(r for r in rows if r['method']=='LK');p(f"Harris+LK tracked {float(lk['good']):.1f} valid points per pair, of which {float(lk['inliers']):.1f} passed the geometric check, at {float(lk['ms']):.2f} ms per pair. Its local small-motion assumption suits neighboring frames, but does not guarantee successful tracking through occlusion or large motion.")
h('LAB5 Drone Visual Tracking Laboratory Report')
p('Name: ____________________  Student ID: ____________________<br/>Experiment dates: 30-31 October 2026')
p('This experiment follows MIT VNAV LAB5. It derives the perspective projection of a sphere and the vanishing point of parallel lines, completes the ROS C++ feature trackers, and compares SIFT, SURF, ORB, FAST+BRIEF and Harris+Lucas-Kanade on an image pair and two real sequences. Farneback dense optical flow is also implemented. Tables are calculated from actual per-pair CSV measurements; figures are screenshots captured inside the Ubuntu virtual machine.')
p('Environment: VMware Ubuntu 20.04, ROS Noetic, GCC 9.4 and a separately compiled OpenCV 4.2.0 with contrib and OPENCV_ENABLE_NONFREE enabled. The isolated workspace is /home/by/lab5_complete/ws.')
figure('01_Ubuntu_ROS_Environment.png','Figure 01 Ubuntu and ROS environment',255)
p('The prescribed bags are 30fps_424x240_2018-10-01-18-35-06.bag and vnav-lab5-smooth-trajectory.bag. One RGB image topic is selected per sequence. Only neighboring images on that topic are paired; depth images and different cameras are not mixed.')
page();h('1 Perspective Projection of a Sphere')
p('For the normalized pinhole camera, the image plane is z=1. An image point (u,v) defines q=(u,v,1) and a ray X=tq, with t&gt;0 for forward visibility. The sphere has radius r and center C=(0,0,d), where d&gt;r+1. Substitution in the sphere equation gives:')
p('(u<super>2</super>+v<super>2</super>+1)t<super>2</super> - 2dt + d<super>2</super>-r<super>2</super> = 0.')
p('Interior image points correspond to rays with real intersections. The silhouette occurs when the discriminant is zero:')
p('d<super>2</super> - (u<super>2</super>+v<super>2</super>+1)(d<super>2</super>-r<super>2</super>) = 0.<br/>Hence u<super>2</super>+v<super>2</super> = r<super>2</super>/(d<super>2</super>-r<super>2</super>).')
p('The projection is a disk with boundary radius r/sqrt(d<super>2</super>-r<super>2</super>). The common expression r/d is only an approximation when the radius is much smaller than the distance.')
p('For an arbitrary center C=(a,b,c), tangency gives the conic:')
p('(au+bv+c)<super>2</super> - (a<super>2</super>+b<super>2</super>+c<super>2</super>-r<super>2</super>)(u<super>2</super>+v<super>2</super>+1) = 0.')
p('If the entire sphere is in front of the camera, c&gt;r. The two eigenvalues of the quadratic part are r<super>2</super>-c<super>2</super> and r<super>2</super>-a<super>2</super>-b<super>2</super>-c<super>2</super>, both negative, so the silhouette is an ellipse. It is a circle when a=b=0. In general, its center is (ac/(c<super>2</super>-r<super>2</super>), bc/(c<super>2</super>-r<super>2</super>)), rather than the perspective projection of the sphere center.')
p('Without the front-of-camera condition, the sphere may cross the camera plane and the conic can be parabolic or hyperbolic. The forward-ray constraint must still be checked. Thus the ellipse statement requires an explicit visibility assumption.')
h('2 Vanishing Points of Parallel Lines')
p('Write two parallel lines as X<sub>1</sub>=P<sub>1</sub>+lambda D and X<sub>2</sub>=P<sub>2</sub>+mu D. Their common direction is D=(D<sub>x</sub>,D<sub>y</sub>,D<sub>z</sub>). The homogeneous projection of the first line is:')
p('[P<sub>x</sub>+lambda D<sub>x</sub> : P<sub>y</sub>+lambda D<sub>y</sub> : P<sub>z</sub>+lambda D<sub>z</sub>].')
p('As the line parameter tends to infinity, both lines approach v=[D<sub>x</sub>:D<sub>y</sub>:D<sub>z</sub>]. If D<sub>z</sub> is nonzero, the finite vanishing point is (D<sub>x</sub>/D<sub>z</sub>,D<sub>y</sub>/D<sub>z</sub>). If D<sub>z</sub>=0, the vanishing point lies at infinity. Each line then has constant depth and its image direction is proportional to (D<sub>x</sub>,D<sub>y</sub>). Their distinct image lines therefore remain parallel.')
p('For distinct, nondegenerate image lines, D<sub>z</sub>=0 is the required parallelism condition. A line through the optical center may collapse to a point; coincident image lines are also excluded from this statement.')
page();h('3 C++ Implementation and Build Verification')
p('The SIFT, SURF, ORB and FAST tracker adapters implement detection, description and matching. FeatureTracker supplies geometric validation, drawing and average statistics. FAST is used only as a detector; a separate BRIEF extractor computes its descriptors.')
p('SIFT and SURF use FLANN two-nearest-neighbor matching. ORB and BRIEF use brute-force Hamming distance. All descriptor methods apply the strict test d<sub>1</sub>&lt;0.8d<sub>2</sub>. Empty descriptors, fewer than two train descriptors and incomplete neighbor lists are handled before accessing matches.')
p('Geometric validation uses fundamental-matrix RANSAC, a 3-pixel epipolar threshold and confidence 0.99. The template algorithm is retained, with the enumeration updated for OpenCV 4. Fewer than eight candidates are not fitted. An empty candidate set has ratio zero. Returned corresponding points retain the same indexing on both images.')
figure('02_Catkin_Build_and_ROS_Test.png','Figure 02 catkin build and ROS launch verification',275)
p('CMake locates the isolated OpenCV installation and links its libraries. cv_bridge converts ROS image messages. The LK shutdown path avoids dereferencing the null descriptor tracker. The first video frame only initializes state and is never matched with itself.')
p('lab5_evaluate is an additional offline evaluator using the same OpenCV algorithms and parameters. It reads every selected rosbag image in order and writes per-pair records and summaries. This avoids dropping frames because of a live message queue or interactive display.')
page();h('ROS Interactive Matching Verification')
figure('16_ROS_Live_SIFT_Window.png','Figure 16 Live matching window of the ROS node',380)
p('The ROS node and offline evaluator are launched separately. FLANN approximation and the RANSAC random state can produce slightly different counts. All comparison tables consistently use the offline evaluator initialized with random seed 42. This screenshot verifies the ROS input and display path.')
page();h('4 SIFT Keypoints and Descriptors')
p('SIFT locates features in scale space, assigns an orientation and describes a local gradient distribution. Its default descriptor contains 4 x 4 x 8 = 128 floating-point components. Descriptor computation may remove keypoints without a valid neighborhood, so statistics use the surviving keypoint counts.')
figure('03_SIFT_Keypoints.png','Figure 03 SIFT keypoints in both images',225)
p('A nearest neighbor alone can yield many false matches. The distance ratio tests whether the best candidate is sufficiently distinct from the second best, rejecting some ambiguities from repeated texture. It does not prove geometric correctness.')
figure('04_SIFT_Raw_Matches.png','Figure 04 Unfiltered SIFT nearest-neighbor matches',225)
page();h('5 Ratio Filtering and Geometric Inliers')
figure('05_SIFT_Ratio_Filter.png','Figure 05 SIFT matches after the ratio test',245)
figure('06_SIFT_RANSAC.png','Figure 06 SIFT geometric inliers and outliers',245)
p('Green marks RANSAC inliers and red marks outliers. Ratio filtering reduces the candidate set; the fundamental matrix then rejects correspondences inconsistent with the estimated epipolar model. The box scene is strongly planar and may be degenerate for fundamental-matrix estimation. An inlier is therefore model-consistent, not necessarily correct according to human ground truth.')
page();h('6 Comparison on the Image Pair')
table('pair')
p('Ratio means inliers divided by ratio-filtered matches. Raw is the number of best candidates, not the total number of elements in all two-neighbor lists. Computation time includes detection, description, matching and geometry, excluding image loading, result drawing and screenshots. A single pair is sensitive to initialization, caches and scheduling.')
figure('07_SURF_RANSAC.png','Figure 07 SURF matching and geometric verification',210)
figure('08_ORB_RANSAC.png','Figure 08 ORB matching and geometric verification',210)
page();h('7 FAST and BRIEF Extension')
figure('09_FAST_BRIEF_RANSAC.png','Figure 09 FAST corners with BRIEF descriptors',270)
p('FAST detects corners but does not compute a descriptor. BRIEF compares intensity pairs to produce a 32-byte binary descriptor. Hamming distance measures differing bits; converting descriptor bytes to floating point and using Euclidean distance would change the meaning of the comparison.')
p('FAST threshold is 20 with nonmaximum suppression. BRIEF uses 32 bytes without additional orientation compensation. ORB uses at most 1000 keypoints and a multiscale pyramid. SURF uses Hessian threshold 400; SIFT uses defaults. The same settings are used on both real sequences.')
p('On the box pair, SIFT produces a stable number of filtered matches and inliers. SURF detects more points, but its inlier ratio does not increase accordingly. ORB produces fewer filtered candidates and relatively inexpensive binary matching. FAST+BRIEF is more sensitive to viewpoint, rotation and scale changes here. These observations describe this experiment, rather than a universal ranking.')
page();h('8 First Real Sequence')
p('Dataset: 30fps_424x240_2018-10-01-18-35-06.bag. Every neighboring RGB frame pair is evaluated, without subsampling or selecting a short segment. Statistics are arithmetic means over frame pairs. The reported ratio is the mean of individual ratios, not total inliers divided by total good matches.')
describe_en(table('dataset1'))
figure('10_Dataset1_Statistics.png','Figure 10 Full-sequence statistics for dataset 1',280)
p('For Harris+LK, Raw and Good both count status-valid, in-bounds tracked points; no descriptor ratio test is applied. KP 2 is the successful track count, while descriptor methods independently detect points in image 2. This difference must be retained when comparing columns.')
page();h('9 Second Real Sequence')
p('Dataset: vnav-lab5-smooth-trajectory.bag. Topic selection and pairing follow the same rule. Its simulated timestamps run from approximately 33.86 s to 103.48 s. The historical dates displayed by rosbag info are a Unix-time interpretation, not the experiment dates. Full records are stored in results/dataset2.')
describe_en(table('dataset2'))
figure('11_Dataset2_Statistics.png','Figure 11 Full-sequence statistics for dataset 2',280)
p('Neighboring video frames usually differ less than the two box images. Binary descriptors and LK can consequently maintain more useful correspondences. Absolute inlier count, candidate retention, inlier ratio and computation time should be considered together.')
page();h('10 Harris Corners and Lucas Kanade Tracking')
p('Brightness constancy assumes I(x,y,t)=I(x+u,y+v,t+1). First-order expansion gives I<sub>x</sub>u+I<sub>y</sub>v+I<sub>t</sub>=0. One pixel does not constrain both motion components. LK assumes similar motion within a local window and solves a least-squares problem. Harris corners provide intensity variation in both directions, improving conditioning.')
p('Parameters are a 21 x 21 window, maximum pyramid level 3, at most 500 Harris corners, quality 0.01 and minimum spacing 8 pixels. The ROS class keeps surviving corners and detects again below 150 points. The offline table detects Harris points anew in each first image, keeping a fixed pairwise evaluation protocol.')
figure('12_Dataset1_LK.png','Figure 12 Harris+LK tracks in dataset 1',205)
figure('13_Dataset2_LK.png','Figure 13 Harris+LK tracks in dataset 2',205)
p('LK relies on approximate brightness constancy, locally coherent motion and sufficiently small displacement for linearization. Pyramids extend the displacement range but do not remove failures caused by occlusion, blur, weak texture or lighting changes. Descriptor methods can rematch over larger motion; LK often has a lower local tracking cost.')
page();h('ROS Video Tracking Verification')
figure('17_ROS_Live_LK_Video.png','Figure 17 ROS rosbag playback and live LK tracking',380)
p('The course video_tracking.launch starts bag playback and the Harris+LK node. The live window verifies image-topic reception, grayscale conversion, status checks and trajectory drawing. Complete tables come from offline traversal, so rendering speed and message queues do not determine which frame pairs are evaluated.')
page();h('11 Farneback Dense Optical Flow')
p('Dense flow is computed between neighboring real frames. Parameters are pyr_scale=0.5, levels=3, winsize=15, iterations=3, poly_n=5 and poly_sigma=1.2. Hue represents direction; value represents flow magnitude normalized within the frame. Saturation is fixed at 255.')
figure('14_Dataset1_Farneback.png','Figure 14 Farneback flow in dataset 1',235)
figure('15_Dataset2_Farneback.png','Figure 15 Farneback flow in dataset 2',235)
p('Per-frame normalization means that brightness cannot be compared across these images as an absolute speed measure. Dense flow covers the full image, including poorly constrained textureless or occluded areas. This extension illustrates the difference between sparse feature trajectories and a dense motion field.')
page();h('12 Conclusions and Reproduction')
p('The completed pipeline includes feature extraction, two-neighbor matching, ratio filtering and RANSAC validation, together with Harris+LK sparse tracking and Farneback dense flow. SIFT and SURF use scale-space features; ORB and FAST+BRIEF provide compact binary descriptors. Performance depends on image texture, motion and parameter choices.')
p('Limitations include model-based rather than ground-truth inlier labels, degeneracy in planar scenes, and differing meanings of KP 2 for LK and descriptor methods. Timings describe one complete traversal in a virtual machine, with background transfers and scheduling effects. They are not hard real-time guarantees.')
p('Build the isolated dependencies with build_opencv.sh. Place feature_tracking under ws/src, change directory to ~/lab5_complete/ws and run:')
p('source /opt/ros/noetic/setup.bash<br/>export OpenCV_DIR=$HOME/lab5_complete/opencv/lib/cmake/opencv4<br/>catkin_make -DCMAKE_BUILD_TYPE=Release<br/>source devel/setup.bash',small)
p('Run bash run_all.sh from ~/lab5_complete for complete evaluation. For interactive matching use two_frames_tracking.launch with descriptor:=SIFT. For video use video_tracking.launch with descriptor:=LK and the required path_to_dataset argument. Full commands are in README_提交说明.md. Press a key to exit the image-pair window or Ctrl+C for video.')
p('Offline usage is lab5_evaluate bag DATASET.bag OUTPUT_DIR METHOD. Available methods are SIFT, SURF, ORB, FAST_BRIEF, LK and FLOW. CSV files, summaries, logs and numbered screenshots are preserved together, allowing the tables to be independently recomputed.')
h('References')
for text in ['MIT VNAV LAB5 Exercises<br/>https://vnav.mit.edu/labs_2023/lab5/exercises.html','MIT-SPARK VNAV labs VNAV2021 release<br/>https://github.com/MIT-SPARK/VNAV-labs/releases/tag/VNAV2021','MIT-SPARK VNAV lab data<br/>https://github.com/MIT-SPARK/VNAV-lab-data','OpenCV 4.2.0 documentation and contrib source<br/>https://docs.opencv.org/4.2.0/<br/>https://github.com/opencv/opencv_contrib/tree/4.2.0/modules/xfeatures2d'] :p(text,small)
p('Upstream revision: 2443ec7e491001d09ab8dd66f6b953177043b784. Implementation and compatibility changes are retained in the source package. Screenshots are actual Ubuntu captures; underlying output images remain in results.',small)
